import{z as i,x as o,o as r,c as d,q as t,j as s,D as A,d as E,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"分层与端到端","description":"","frontmatter":{"title":"分层与端到端","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/layering-e2e.md","filePath":"cs/layering-e2e.md","lastUpdated":1791413859000}'),p={name:"cs/layering-e2e.md"};function m(C,a,D,f,c,h){const B=o("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="分层与端到端" tabindex="-1">分层与端到端 <a class="header-anchor" href="#分层与端到端" aria-label="Permalink to &quot;分层与端到端&quot;">​</a></h1><div class="epigraph"><p>功能只应放在端系统能完成且正确的那一层；下层的「几乎正确」不能代替端到端的检查。</p><footer>—— 据 Saltzer, Reed and Clark, End-to-End Arguments in System Design, ACM TOCS 1984 整理</footer></div><p><a href="/cs/distributed-os-intuition">上一课</a>把透明分布式 Unix 挡在延迟与分区外：实践是单机内核加显式网络与编排，操作系统进阶课序到此结束。<a href="/cs/io-dma">I/O 与 DMA</a>已经能把设备字节搬进一台机器的内存。两台机器之间还没有共享的名字：对方的缓冲不是我的物理帧，总线事务过不了机箱。缺口是<strong>互连</strong>：先约定分层，再用端到端论证约束「可靠性该放哪」。本课不把 MAC 地址写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把文件语义（完整字节流、进程描述符）直接铺到电线上，每种应用都要重做调制。若只在链路上做完美可靠，文件传输仍要在两端核对：链路重传挡不住中间节点内存出错。Saltzer 等的论证：文件传送的正确性只能在两端用校验与重试保证；链路层的努力是性能优化，不是正确性替代。缺口是这句分工，加上分层：相邻层通过接口服务，对等层通过协议。</p><p>套接字需要<a href="/cs/process-image">进程</a>与<a href="/cs/file-bytestream">文件</a>，但本课还没有端口；只承认「主机」将出现。</p><p><span class="marginnote">端到端不是「不要下层校验」。下层校验降低端到端重传频率。论证反对的是：把端到端才能做对的功能只放在下层并声称已经够了。</span></p><p><span class="marginnote">术语翻译：「接口服务」与「对等协议」——接口是同一台机器内上下层之间的纵向调用（网络层调用链路层递包）；对等协议是两台机器同一层之间的横向约定（你的网络层和我的网络层说同一种语言）。分层 = 纵向靠接口，横向靠协议。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>教学用五层直觉：应用、传输、网络、链路、物理。IP 把异构链路连成互联网（Cerf 与 Kahn 的分组互连）；传输把进程接上；链路把相邻跳接上。本课不把 OSI 七层当必须背诵的真理，只要求：每层有 PDU 与对等协议，上层 PDU 是下层的载荷。</p>',10)),(r(),s(n,null,{default:A(()=>[l(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20TR%5B%22%E4%BC%A0%E8%BE%93%3A%20%E8%BF%9B%E7%A8%8B%E5%88%B0%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20TR%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%3A%20%E4%B8%BB%E6%9C%BA%E5%88%B0%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20NET%20--%3E%20LINK%5B%22%E9%93%BE%E8%B7%AF%3A%20%E4%B8%80%E8%B7%B3%22%5D%0A%20%20LINK%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("分层让 DMA 进来的字节被解释成帧、包、段，而不是「又一份磁盘块」。端到端论证解释后课 TCP 校验与应用层校验为何同时存在：磁盘与路由器内存都不在文件两端的信任域里。VFS 的 "),e("code",null,"read"),E(" 在一台机器上结束；跨机器必须把「流」做成协议，而不是共享 inode。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：链路层校验像快递每一段航班的装卸核对——每段都核对得再仔细，也防不住包裹在中转仓库里受潮；只有收件人开箱验货（两端核对校验和）才能发现内容真的坏了。中转仓库就是路由器内存，它不属于任何一段「航线」的核对范围。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「下层已经有 CRC 校验，上层校验是重复劳动」。实际上下层校验只把出错概率降一个量级，永远到不了零——中间节点的内存翻转、网卡 DMA 写错位置都不在任何一跳的校验里。TCP 校验与应用校验同时存在，不是历史包袱。")],-1)),(r(),s(n,null,{default:A(()=>[l(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8F%91%E9%80%81%E7%AB%AF%3A%20%E5%86%99%E5%85%A5%E5%AE%8C%E6%95%B4%E6%96%87%E4%BB%B6%22%5D%20--%3E%20A%5B%22%E9%93%BE%E8%B7%AFA%3A%20%E5%B8%A7%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%2C%20%E5%AE%8C%E5%A5%BD%E9%80%81%E8%BE%BE%22%5D%0A%20%20A%20--%3E%20R%5B%22%E4%B8%AD%E9%97%B4%E8%B7%AF%E7%94%B1%E5%99%A8%3A%20%E5%AD%98%E5%85%A5%E5%86%85%E5%AD%98%E6%97%B6%E6%AF%94%E7%89%B9%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20R%20--%3E%20B%5B%22%E9%93%BE%E8%B7%AFB%3A%20%E5%AF%B9%E6%94%B6%E5%88%B0%E7%9A%84%E9%94%99%E8%AF%AF%E6%95%B0%E6%8D%AE%E6%A0%A1%E9%AA%8C%2C%20%E4%BE%9D%E7%84%B6%E9%80%9A%E8%BF%87%22%5D%0A%20%20B%20--%3E%20RC%5B%22%E6%8E%A5%E6%94%B6%E7%AB%AF%3A%20%E6%94%B6%E5%88%B0%E6%8D%9F%E5%9D%8F%E5%AD%97%E8%8A%82%2C%20%E9%80%90%E8%B7%B3%E9%83%BD%E6%B2%A1%E6%8A%A5%E8%AD%A6%22%5D%0A%20%20RC%20--%3E%20E2E%5B%22%E5%8F%AA%E6%9C%89%E4%B8%A4%E7%AB%AF%E8%87%AA%E5%B7%B1%E7%9A%84%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%A0%A1%E9%AA%8C%E8%83%BD%E5%8F%91%E7%8E%B0%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>这张图回答的问题：每一跳都「校验通过」，文件为什么会坏。答案画在中间节点——损坏发生在没有任何一层校验覆盖的位置（路由器内存里），所以正确性必须在真正的两端收口，逐跳校验只是把重传概率降下来的性能优化。</p><p>本课之后，先对照五层与四层两种切法，第一跳如何给帧加上可转发的链路地址，是后面<a href="/cs/frame-mac">帧与 MAC</a>一课的事。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入跨层优化的全部例外（有意识地打破分层），不把电信信令网当互联网主干。也不把端到端与「网络中立」政策混成一课。加密与认证的端到端是更后的 TLS 入口，这里只借 Saltzer 的文件传输例子。</p><p>把加密只放在链路层，换一条跳就明文：这也是端到端要把机密性放到真正两端的理由，后课 TLS 入口会收回。</p><p>后课默认：功能按层放；正确性在真正的两端收口。相邻机器上的一跳需要帧与硬件地址，是后面<a href="/cs/frame-mac">帧与 MAC</a>一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DMA 只解决单机搬字节；跨机要协议分层。</li><li>端到端：下层优化性能，两端保证正确。</li><li>一跳的帧与硬件地址是后面<a href="/cs/frame-mac">帧与 MAC</a>一课的缺口。</li><li>出处：Saltzer, Reed and Clark, <em>ACM TOCS</em> 1984；Cerf and Kahn, 1974；Kurose and Ross。</li></ul>',8))])}const F=i(p,[["render",m]]);export{T as __pageData,F as default};
